module.exports = "<!--\r\n  Controller As 'inviteRespond'\r\n\r\n  Access the current mode to display with scope access\r\n    inviteRespond.mode\r\n\r\n  All modes\r\n    'no-code'\r\n      warn user there is no code to show and give link to login view, maybe auto-redirect\r\n      (Needs UX review - currently just redirects to login)\r\n\r\n    'loading'\r\n      inform user their information is being retrieved from the  server: show a loading spinner or something\r\n\r\n    'expired-code'\r\n      Inform user the code they used is expired and provide a button to request a new code via email\r\n\r\n    'no-invite'\r\n      Inform user the invitation does not exist. It may have been cancelled or accepted/rejected already\r\n\r\n    'valid-code'\r\n      Display the invitation data and allow the user accept, reject, or ignore the code and go to their home screen\r\n\r\n    'error'\r\n      an unexpected error occurred. warn user? Plausibly lack of connection\r\n-->\r\n\r\n<ion-view\r\n  class=\"wizard\"\r\n  title=\"{{'auth.invite.referral.response.title' | translate}}\"\r\n  cache-view=\"false\"\r\n  ng-init=\"inviteRespond.mode = 'valid-code'\">\r\n  <div class=\"wizard setup-section ref-response\">\r\n\r\n    <div class=\"welcome\" translate=\"auth.invite.title\" ng-hide=\"inviteRespond.mode == 'loading'\"></div>\r\n\r\n    <div class=\"loading-message\" ng-show=\"inviteRespond.mode == 'loading'\">\r\n      <span translate=\"auth.invite.loading.message\"></span>\r\n      <ion-spinner icon=\"spiral\"></ion-spinner>\r\n    </div>\r\n\r\n    <!-- Start: Confirm-specific section -->\r\n\r\n    <div>\r\n      <div ng-show=\"inviteRespond.mode == 'valid-code'\">\r\n        {{'auth.invite.accept.long' | translate}}&nbsp;\r\n        <span class=\"ref-org\">{{inviteRespond.invite.organizationName}}</span>?\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"confirmation-opts\" ng-show=\"inviteRespond.mode == 'valid-code'\">\r\n      <div class=\"decline\" ng-click=\"inviteRespond.reject()\" translate=\"auth.invite.decline\"></div>\r\n      <div class=\"accept\" ng-click=\"inviteRespond.accept()\" translate=\"auth.invite.accept\"></div>\r\n    </div>\r\n\r\n    <!-- End: Confirm-specific section -->\r\n\r\n    <!-- State based message and input button -->\r\n\r\n    <div>\r\n      <span class=\"space-bottom\" ng-show=\"inviteRespond.message\" translate=\"{{inviteRespond.message}}\"></span>\r\n    </div>\r\n\r\n    <div ng-show=\"inviteRespond.action\">\r\n      <div class=\"register new-code\" ng-click=\"inviteRespond.action()\">\r\n        <div translate=\"{{inviteRespond.button}}\"></div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</ion-view>";

